#!/usr/bin/env python3

# Assemble the Copilot code review instructions for the xDS API. Usage:
#
# bazel run //tools/api/review_instructions:generate -- --mode=<check|fix>
#
# Copilot code review cannot follow links from its instructions file, so the canonical API docs
# under api/ are inlined after a hand-written, review-specific header. Edit those docs or
# header.md, never the generated file.

import argparse
import os
import pathlib
import sys
from typing import NamedTuple, Sequence


class Paths(NamedTuple):
    header: pathlib.Path
    sources: Sequence[pathlib.Path]
    output: pathlib.Path


def repo_paths(root: pathlib.Path) -> Paths:
    return Paths(
        header=root / 'tools/api/review_instructions/header.md',
        sources=[
            root / 'api/API_VERSIONING.md',
            root / 'api/STYLE.md',
            root / 'api/review_checklist.md',
        ],
        output=root / '.github/instructions/api-review.instructions.md')


def render(header: str, sources: Sequence[tuple[str, str]]) -> str:
    """Return the instructions file for a header and (repo relative path, content) sources.

    The header must start with the YAML frontmatter that Copilot reads, so the generated notice is
    placed after it.
    """
    if not header.startswith('---\n'):
        raise ValueError('header must start with YAML frontmatter')
    end = header.index('\n---\n', len('---\n')) + len('\n---\n')
    source_list = ', '.join(path for path, _ in sources)
    parts = [
        header[:end].rstrip('\n'),
        f'<!-- Generated by tools/api/review_instructions/generate.py from '
        f'tools/api/review_instructions/header.md, {source_list}. Do not edit; edit those files '
        f'and run ./tools/proto_format/proto_format.sh fix. -->',
        header[end:].strip('\n'),
    ]
    parts.extend(content.strip('\n') for _, content in sources)
    return '\n\n'.join(parts) + '\n'


def generate(root: pathlib.Path) -> str:
    paths = repo_paths(root)
    return render(
        paths.header.read_text(),
        [(str(path.relative_to(root)), path.read_text()) for path in paths.sources])


def main(argv: Sequence[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--mode', choices=['check', 'fix'], required=True)
    parser.add_argument(
        '--root',
        type=pathlib.Path,
        default=pathlib.Path(os.environ.get('BUILD_WORKSPACE_DIRECTORY', '.')),
        help='Envoy source root (defaults to the bazel workspace).')
    args = parser.parse_args(argv)

    output = repo_paths(args.root).output
    expected = generate(args.root)
    actual = output.read_text() if output.exists() else ''
    if actual == expected:
        return 0
    if args.mode == 'fix':
        output.write_text(expected)
        return 0
    print(
        f'{output.relative_to(args.root)} is out of date with the API docs. '
        'Run ./tools/proto_format/proto_format.sh fix.',
        file=sys.stderr)
    return 1


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
